export function Logout({
  heading = "{{heading}}",
  accountName = "{{accountName}}",
  style = "{{style}}",
  allDevices = {{allDevices}},
  accent = "{{accent}}",
}) {
  const dialog = style === "Dialog";
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: dialog ? "#FAF7F2" : "#24143008", width: 300, padding: 20, borderRadius: dialog ? 14 : 8, boxSizing: "border-box",
      border: dialog ? "1px solid #24143018" : "none", borderLeft: dialog ? undefined : `4px solid ${accent}`, boxShadow: dialog ? "0 10px 30px rgba(36,20,48,.18)" : "none" }}>
      <h3 style={{ margin: "0 0 6px", fontSize: 16 }}>{heading}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 13, color: "#24143099" }}>Signed in as <strong>{accountName}</strong></p>
      {allDevices && <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 14 }}><input type="checkbox" />Sign out of all devices</label>}
      <div style={{ display: "flex", gap: 10 }}>
        <button type="button" style={{ flex: 1, padding: 9, borderRadius: 8, fontWeight: 700, cursor: "pointer", font: "inherit", background: "transparent", border: "1.5px solid #24143030", color: "#241430" }}>Cancel</button>
        <button type="button" style={{ flex: 1, padding: 9, borderRadius: 8, fontWeight: 700, cursor: "pointer", font: "inherit", background: accent, border: "none", color: "#FAF7F2" }}>Sign out</button>
      </div>
    </div>
  );
}
